import React, { useState } from 'react';
import PropTypes from 'prop-types';
import './StockSearch.css';

function StockSearch({ onStockFound }) {
    const [searchTerm, setSearchTerm] = useState('');
    const [error, setError] = useState(null);
    const [isLoading, setIsLoading] = useState(false);

    const handleSearch = async () => {
        if (!searchTerm.trim()) {  
            setError('Please enter a stock symbol');
            return;
        }

        try {
            setError(null);
            setIsLoading(true);
            const response = await fetch(`http://localhost:8082/api/stocks/search/${searchTerm.toUpperCase()}`);
            if (!response.ok) {
                throw new Error('Stock not found');
            }
            const data = await response.json();
            onStockFound(data);  
            setSearchTerm(''); 
        } catch (error) {
            setError(error instanceof Error ? error.message : 'An error occurred');
        } finally {
            setIsLoading(false);
        }
    };

    const handleKeyPress = (e) => {
        if (e.key === 'Enter') {
            handleSearch();
        }
    };

    return (
        <div className="stock-search">
            <div className="search-container">
                <input
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value.toUpperCase())}
                    onKeyPress={handleKeyPress}
                    placeholder="Enter stock symbol (e.g., AAPL)"
                    className={error ? 'error' : ''}
                    disabled={isLoading}
                />
                <button 
                    onClick={handleSearch}
                    disabled={isLoading || !searchTerm.trim()}
                    className={isLoading ? 'loading' : ''}
                >
                    {isLoading ? 'Searching...' : 'Search'}
                </button>
            </div>
            {error && <p className="error-message">{error}</p>}
            <div className="example-symbols">
                Try: AAPL, MSFT, GOOGL, AMZN, TSLA
            </div>
        </div>
    );
}

StockSearch.propTypes = {
    onStockFound: PropTypes.func.isRequired
};

export default StockSearch;
